package dev.gbppimentel.snapcompanion;
import org.junit.Test;import static org.junit.Assert.*;
public class ResearchSyncGateTest {
 @Test public void readsOnlyOnSaveChangeOrAQuietSceneEntry(){var g=new ResearchSyncGate();assertFalse(g.ready("a",false,1000));assertTrue(g.ready("a",true,2000));g.accepted(2000);assertFalse(g.ready("a",true,60000));assertFalse(g.ready("a",false,61000));assertTrue(g.ready("a",true,62000));g.accepted(62000);assertTrue(g.ready("b",true,62500));}
 @Test public void briefQuietTransitionsWaitForCooldownWithoutBecomingPermanentPolling(){var g=new ResearchSyncGate();assertTrue(g.ready("a",true,1000));g.accepted(1000);assertFalse(g.ready("a",false,2000));assertFalse(g.ready("a",true,3000));assertTrue(g.ready("a",true,16000));g.accepted(16000);assertFalse(g.ready("a",true,100000));}
 @Test public void aFailedUnchangedSnapshotRetriesWithBackoffButNotDuringAnExpedition(){var g=new ResearchSyncGate();assertTrue(g.ready("a",true,1000));g.failed(1000);assertFalse(g.ready("a",true,3999));assertFalse(g.ready("a",false,4000));assertTrue(g.ready("a",true,4500));g.failed(4500);assertFalse(g.ready("a",true,10499));assertTrue(g.ready("a",true,10500));}
 @Test public void profileSwitchAndClockRollbackDoNotReuseAnOldWait(){var g=new ResearchSyncGate();assertTrue(g.ready("profile1:a",true,1000));g.failed(1000);assertTrue(g.ready("profile2:a",true,1500));g.accepted(1500);assertTrue(g.ready("profile2:a",true,500));g.accepted(500);assertFalse(g.ready("",true,600));assertTrue(g.ready("profile2:a",true,700));}
 @Test public void lateAuxiliarySaveInAnUnchangedQuietSceneRefreshesWithoutPollingCopies(){var g=new ResearchSyncGate();assertTrue(g.ready("profile:user:photoHash:revision1",true,1000));g.accepted(1000);assertFalse(g.ready("profile:user:photoHash:revision1",true,20000));assertTrue(g.ready("profile:user:photoHash:revision2",true,21000));g.accepted(21000);assertFalse(g.ready("profile:user:photoHash:revision2",true,100000));assertFalse(g.ready("profile:user:photoHash:revision3",false,101000));assertTrue(g.ready("profile:user:photoHash:revision3",true,102000));}
}
